export const curriculum=studyBlocks.map((b,i)=>({...b,index:i,phase:i<6?0:i<10?1:i<13?2:3}));
export function lessonFor(id){if(id.startsWith('u:')){const u=units.find(x=>x.id===id.slice(2));return {...u,id,concept:u.goal,task:u.transfer,video:videos[u.video]?.id};}if(id.startsWith('i:')){const u=instrumentLessons.find(x=>x.id===id.slice(2));return {...u,id,minutes:15,concept:u.steps.map(x=>x[1]).join(' '),task:'Configura el instrumento siguiendo las indicaciones. Comprueba cada ajuste en la pantalla del instrumento.',video:videos[u.video]?.id};}return foundationLessons.find(x=>x.id===id);}
const phaseNames=['Conoce las piezas','Conecta las ideas','Interpreta un equipo','Resuelve una avería'];
const phaseNotes=['Una pieza cada vez. Sin saltarte los fundamentos.','De las magnitudes al esquema y de este al cobre.','Señales, alimentación, control y fuerza.','Hipótesis, medidas y una conclusión demostrable.'];
const names=['Resistencias','Condensadores','Bobinas','Diodos','Transistores','Redes'];
const glyphs=['Ω','⊣','∿','▷','⑂','⌁'];
export function componentArt(type=0){const defs='<defs><linearGradient id="metal" x2="0" y2="1"><stop stop-color="#f5faff"/><stop offset=".45" stop-color="#80929f"/><stop offset=".65" stop-color="#e6edf4"/><stop offset="1" stop-color="#526370"/></linearGradient><linearGradient id="body" x2="0" y2="1"><stop stop-color="#ffe5ad"/><stop offset=".45" stop-color="#cfb079"/><stop offset="1" stop-color="#867052"/></linearGradient><linearGradient id="blue" x2="1" y2="1"><stop stop-color="#72c9ff"/><stop offset=".4" stop-color="#27649b"/><stop offset="1" stop-color="#0b263f"/></linearGradient></defs>';
let art=type===0?'<path d="M40 128H180M360 128H490" stroke="#b8c7d4" stroke-width="10"/><rect x="169" y="91" width="202" height="74" rx="32" fill="url(#body)"/><g><path d="M203 92V164" stroke="#6a351d" stroke-width="16"/><path d="M237 92V164" stroke="#15191e" stroke-width="16"/><path d="M277 92V164" stroke="#ed3a30" stroke-width="16"/><path d="M333 93V163" stroke="#d9af44" stroke-width="13"/></g><path d="M182 106H358" stroke="#fff7dd" opacity=".4" stroke-width="4"/><text x="268" y="215">1 kΩ ±5 % · MARRÓN / NEGRO / ROJO / ORO</text>':type===1?'<path d="M225 170V230M298 170V230" stroke="#b8c7d4" stroke-width="9"/><rect x="188" y="45" width="150" height="148" rx="20" fill="url(#blue)"/><ellipse cx="263" cy="47" rx="73" ry="18" fill="url(#metal)"/><path d="M215 38L309 57M218 59L307 35" stroke="#4d5f6d" stroke-width="2"/><rect x="300" y="65" width="22" height="113" fill="#b9d9ee"/><path d="M304 95H318M304 129H318M304 163H318" stroke="#143552" stroke-width="3"/><text x="244" y="118" fill="#fff" style="font-size:23px">100 µF</text><text x="244" y="147" fill="#fff">25 V</text>':type===2?'<path d="M185 150L135 225M333 150L384 225" stroke="#b8c7d4" stroke-width="8"/><ellipse cx="260" cy="123" rx="102" ry="75" fill="#252c35" stroke="#647582" stroke-width="3"/><ellipse cx="260" cy="123" rx="42" ry="31" fill="#0c131b"/>'+Array.from({length:12},(_,i)=>`<path d="M${176+i*15} ${93-Math.sin(i/11*Math.PI)*27} Q${155+i*18} 160 ${188+i*13} ${166+Math.sin(i/11*Math.PI)*14}" fill="none" stroke="#dc9c57" stroke-width="10"/>`).join(''):type===3?'<path d="M50 130H200M340 130H480" stroke="#b8c7d4" stroke-width="8"/><rect x="189" y="96" width="156" height="68" rx="14" fill="#242e3a" stroke="#718192"/><rect x="315" y="96" width="15" height="68" fill="#ccd8df"/><text x="256" y="138" fill="#fff">1N4007</text><text x="332" y="205">CÁTODO</text><path d="M332 185V170" stroke="#59d9ce"/>':type===4?'<path d="M210 162V234M266 162V234M322 162V234" stroke="#b8c7d4" stroke-width="12"/><rect x="197" y="24" width="138" height="104" rx="7" fill="url(#metal)"/><circle cx="266" cy="51" r="15" fill="#0c131b"/><rect x="188" y="83" width="156" height="99" rx="8" fill="#212b36" stroke="#62717f"/><text x="265" y="121" fill="#f5f7fa">MOSFET</text><text x="265" y="145" fill="#a5b6c4">G · D · S</text>':'<g fill="none" stroke="#61dac7" stroke-width="5"><path d="M90 70H200V140H340V70H450M90 220H200V140M340 140V220H450"/></g><g fill="#d4af63">'+[[90,70],[90,220],[450,70],[450,220],[200,140],[340,140]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="9"/>`).join('')+'</g>';
return `<svg class="componentArt" viewBox="0 0 530 270" role="img" aria-label="Ilustración de ${names[type]}">${defs}<ellipse cx="270" cy="236" rx="175" ry="11" fill="#000" opacity=".25"/><g font-family="monospace" text-anchor="middle" font-size="12" fill="#9cabbc">${art}</g></svg>`;}

export function mountWorkshop(api){
const $=id=>document.getElementById(id),read=(key,fallback)=>{try{return JSON.parse(api.storage.getItem(key))||fallback;}catch{return fallback;}};
let progress=read('circuitlab-plan-v11',{}),extra=read('elektronika-workshop-progress',{}),notes=read('elektronika-workshop-notes',{}),current=read('elektronika-workshop-current',null),screen='home',phase=0,tabStep=0;
const legacy=read('circuitlab-studio-v7',{}), oldInstruments=read('circuitlab-instruments-v8',[]);for(const [id,value] of Object.entries(legacy))if(value?.passed&&!progress['u:'+id])progress['u:'+id]={passed:true,quiz:true};if(Array.isArray(oldInstruments))for(const id of oldInstruments)if(!progress['i:'+id])progress['i:'+id]={passed:true,quiz:true};
const route=curriculum.flatMap(b=>b.lessons),passed=id=>!!(progress[id]?.passed||extra[id]?.passed),next=()=>route.find(id=>!passed(id))||route[0];
const save=()=>{try{api.storage.setItem('circuitlab-plan-v11',JSON.stringify(progress));api.storage.setItem('elektronika-workshop-progress',JSON.stringify(extra));api.storage.setItem('elektronika-workshop-notes',JSON.stringify(notes));api.storage.setItem('elektronika-workshop-current',JSON.stringify(current));$('saveState').textContent='Guardado en este dispositivo';}catch{$('saveState').textContent='No se pudo guardar; exporta tu progreso';}};
document.body.className='workshop';document.title='Elektronika Lab · Aprende desde dentro';
const oldHeader=document.querySelector('body > header');oldHeader.hidden=true;
const shell=document.createElement('div');shell.id='workshopShell';shell.innerHTML=`<aside class="wRail"><a href="#home" class="wBrand" aria-label="Elektronika Lab, inicio"><span class="wLogo">e<span>·</span></span><span>elektronika<b>LAB / 02</b></span></a><span class="wRailLabel">TU LABORATORIO PERSONAL</span><nav aria-label="Navegación principal">${[['home','⌂','Mi aprendizaje'],['course','▤','Aprender'],['experiment','∿','Experimentar'],['boards','▦','Explorar placas'],['diagnose','⌕','Diagnosticar'],['notebook','▧','Mi cuaderno']].map(([id,ico,label])=>`<button data-route="${id}"><span>${ico}</span>${label}<i>↗</i></button>`).join('')}</nav><div class="wRailBottom"><span class="wLive"></span> PRÁCTICA VIRTUAL · 5 V<p id="saveState">Guardado en este dispositivo</p><button id="wTheme">◐ Cambiar tema</button><button id="wExport">↓ Exportar progreso</button></div></aside><div class="wBody"><header class="wTop"><div><span class="wCrumb">ELEKTRONIKA LAB</span><b id="wLocation">Mi aprendizaje</b></div><div><span class="wVersion">NUEVA EXPERIENCIA / 02</span><button id="wThemeTop" aria-label="Cambiar tema">◐</button><button id="wResume">Continuar <span>↗</span></button></div></header><div id="wContent"></div></div><nav class="wMobile" aria-label="Navegación móvil">${[['home','⌂','Inicio'],['course','▤','Aprender'],['experiment','∿','Practicar'],['boards','▦','Placas'],['notebook','▧','Cuaderno']].map(([id,ico,label])=>`<button data-route="${id}"><span>${ico}</span>${label}</button>`).join('')}</nav>`;document.body.prepend(shell);
const content=$('wContent');const oldMain=document.querySelector('body > main');oldMain.id='engineHost';oldMain.hidden=true;document.querySelectorAll('#coursePage,#libraryPage').forEach(p=>p.hidden=true);
const lab=$('labPage'),scope=$('scopePage');
// The engine remains one live instance; the replacement shell owns its placement.
const labTools=document.createElement('div');labTools.className='wLabTools';labTools.innerHTML='<button id="wBackLesson">← Volver a la lección</button><span>PLACA + ESQUEMA + MEDIDA</span><button id="wOpenSignal">Abrir instrumentos de señales ↗</button>';
lab.prepend(labTools);$('wBackLesson').onclick=()=>openLesson(current?.id||next(),current?.step||0);$('wOpenSignal').onclick=()=>navigate('signals');
const aside=lab.querySelector('.lesson');const missionList=aside.querySelector('#missions'),filter=aside.querySelector('.exerciseFilters');const missionDrawer=document.createElement('details');missionDrawer.className='wMissionDrawer';missionDrawer.innerHTML='<summary>Elegir otro reto</summary>';missionDrawer.append(filter,missionList);aside.append(missionDrawer);
const more=document.createElement('details');more.className='wAdvanced';more.innerHTML='<summary>Cuaderno de pistas, metodología y referencias</summary>';const center=lab.querySelector('.center');for(const el of [...center.children])if(!el.classList.contains('viewer'))more.append(el);center.append(more);
const inspector=more.querySelector('.detail');if(inspector){inspector.classList.add('wInspector');center.insertBefore(inspector,more);}
const labIntro=lab.querySelector('.intro');if(labIntro){labIntro.hidden=true;oldMain.append(labIntro);}
let benchHome=$('sharedBenchHome');
function park(){if(lab.parentElement!==oldMain)oldMain.append(lab);if(scope.parentElement!==oldMain)oldMain.append(scope);lab.hidden=true;scope.hidden=true;if($('sharedBench'))benchHome.append($('sharedBench'));document.querySelectorAll('video').forEach(v=>v.pause());globalThis.speechSynthesis?.cancel();}
function updateNav(){document.querySelectorAll('[data-route]').forEach(b=>{const selected=b.dataset.route===(screen==='lesson'?'course':screen==='lab'?'boards':screen);b.classList.toggle('selected',selected);b.setAttribute('aria-current',selected?'page':'false');});$('wLocation').textContent={home:'Mi aprendizaje',course:'Ruta de aprendizaje',lesson:'Lección en curso',experiment:'Mesa de experimentos',boards:'Explorador de placas',lab:'Banco de trabajo',signals:'Instrumentos de señales',diagnose:'Diagnóstico guiado',notebook:'Mi cuaderno'}[screen]||'';}
function navigate(page){park();screen=page;updateNav();content.innerHTML='';if(page==='home')home();else if(page==='course')course();else if(page==='boards')boardCatalog();else if(page==='experiment')experiment();else if(page==='diagnose')diagnose();else if(page==='notebook')notebook();else if(page==='signals'){scope.hidden=false;content.append(scope);window.dispatchEvent(new Event('resize'));}window.scrollTo?.({top:0,behavior:'instant'});}
function heading(kicker,title,description){return `<div class="wHeading"><span class="wEyebrow">${kicker}</span><h1>${title}</h1><p>${description}</p></div>`;}
function bindLessons(root=content){root.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>openLesson(b.dataset.lesson));root.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));}
function home(){const id=current?.id&&route.includes(current.id)&&!passed(current.id)?current.id:next(),l=lessonFor(id),b=curriculum.find(b=>b.lessons.includes(id)),count=route.filter(passed).length;
content.innerHTML=`<section class="wHero"><div class="wHeroCopy"><span class="wEyebrow"><i></i> DE LA PRIMERA PIEZA AL DIAGNÓSTICO</span><h1>Entiende.<br>Experimenta.<br><em>Repara con criterio.</em></h1><p>Tu mesa de trabajo para aprender electrónica.<br>Una idea clara. Una prueba. Un descubrimiento.</p><button class="wPrimary" data-lesson="${id}">${count?'Continuar mi aprendizaje':'Empezar desde cero'} <span>↗</span></button><small>Sin conocimientos previos · a tu ritmo</small></div><div class="wHeroObject"><div class="wObjectTop"><span>01 / ANATOMÍA DE UN COMPONENTE</span><b>R1</b></div>${componentArt(0)}<div class="wObjectData"><div><small>RESISTENCIA</small><strong>1.000 <em>Ω</em></strong></div><div><small>TOLERANCIA</small><strong>±5 <em>%</em></strong></div></div><div class="wObjectCaption"><span class="wLive"></span> Aprende a leer lo que tienes delante</div></div></section><div class="wProgressRow"><div><strong>${count}</strong><span>de ${route.length} lecciones<br>completadas</span></div><progress max="${route.length}" value="${count}" aria-label="Progreso del curso"></progress><span>${Math.round(count/route.length*100)} %</span><button data-go="course">Ver mi ruta →</button></div><section class="wNext"><div class="wNextNumber">${String(b.index+1).padStart(2,'0')}</div><div><span class="wEyebrow">${current?.id===id?'RETOMA DONDE LO DEJASTE':'TU SIGUIENTE PASO'} / ${esc(b.title)}</span><h2>${esc(l.title)}</h2><p>${l.minutes||15} min · Entender → observar → practicar → comprobar</p></div><button class="wRound" data-lesson="${id}" aria-label="Abrir siguiente lección">↗</button></section><div class="wSectionHead"><div><span class="wEyebrow">EL RECORRIDO</span><h2>De una pieza a un sistema.</h2></div><button data-go="course">16 bloques de aprendizaje ↗</button></div><div class="wPhaseGrid">${phaseNames.map((n,i)=>`<button class="wPhaseCard" data-phase="${i}"><span>0${i+1} <i>${['Ω','⌁','▦','⌕'][i]}</i></span><h3>${n}</h3><p>${phaseNotes[i]}</p><b>${curriculum.filter(b=>b.phase===i).flatMap(b=>b.lessons).length} lecciones <span>→</span></b></button>`).join('')}</div><div class="wSectionHead"><div><span class="wEyebrow">TAMBIÉN PUEDES EMPEZAR POR AQUÍ</span><h2>Abre tu banco.</h2></div></div><div class="wExplorePair"><button data-go="experiment"><div class="wWaveArt"><svg viewBox="0 0 440 100"><path d="M0 50H440M0 25H440M0 75H440" stroke="#254552"/><path d="M0 50Q27 -25 55 50T110 50T165 50T220 50T275 50T330 50T385 50T440 50" stroke="#e9c069" stroke-width="3" fill="none"/><path d="M0 62Q28 17 55 62T110 62T165 62T220 62T275 62T330 62T385 62T440 62" stroke="#6dddc8" stroke-width="3" fill="none"/></svg></div><span>01 / INSTRUMENTOS CONECTADOS</span><h3>Haz visible una señal. ↗</h3><p>Generador, osciloscopio y multímetro sobre el mismo circuito.</p></button><button data-go="boards"><div class="wBoardPreview">${boardThumbnail(api.boards.find(x=>x.id==='ardumoto'))}</div><span>02 / EXPLORACIÓN 3D</span><h3>Descubre qué conecta cada pista. ↗</h3><p>Gira, voltea, separa bloques y relaciona la placa con el esquema.</p></button></div>`;bindLessons();content.querySelectorAll('[data-phase]').forEach(b=>b.onclick=()=>{phase=+b.dataset.phase;navigate('course');});}
function course(){content.innerHTML=heading('APRENDER / UN CAMINO, PASO A PASO','Empieza pequeño.<br><em>Llega más lejos.</em>','Resistencias, condensadores, bobinas, diodos y transistores. Después, redes, instrumentos y diagnóstico.')+`<div class="wPhaseTabs" role="group" aria-label="Etapa del curso">${phaseNames.map((p,i)=>`<button data-phase="${i}" aria-pressed="${phase===i}">0${i+1} <span>${p}</span></button>`).join('')}</div><div class="wCourseGrid">${curriculum.filter(b=>b.phase===phase).map(b=>`<section class="wCourseBlock"><div class="wBlockArt">${b.index<6?componentArt(b.index):`<span class="wBlockGlyph">${['V / I','R C L','V ⎓','⌁','∿','⚡','01','⌕','⌘','✓'][b.index-6]}</span>`}<span class="wBlockNo">BLOQUE ${String(b.index+1).padStart(2,'0')}</span></div><div class="wBlockBody"><h2>${esc(b.title)}</h2><p>${esc(b.goal)}</p><div class="wLessonList">${b.lessons.map((id,j)=>`<button data-lesson="${id}" class="${id===next()?'next':''}"><span>${passed(id)?'✓':String(j+1).padStart(2,'0')}</span><b>${esc(lessonFor(id).title)}</b><small>${passed(id)?'Hecha':(lessonFor(id).minutes||15)+' min'}</small><i>↗</i></button>`).join('')}</div><details><summary>Qué sabrás al terminar</summary><p>${esc(b.checkpoint)}</p></details></div></section>`).join('')}</div>`;bindLessons();content.querySelectorAll('[data-phase]').forEach(b=>b.onclick=()=>{phase=+b.dataset.phase;course();});}
function openLesson(id,step=0){const l=lessonFor(id);if(!l)return;park();screen='lesson';current={id,step};tabStep=step;save();updateNav();const b=curriculum.find(b=>b.lessons.includes(id)),art=b.index<6?componentArt(b.index):null,c=circuits.find(c=>c.id===l.pattern);const st=progress[id]||extra[id]||{};
const panels=[`<span class="wEyebrow">UNA IDEA, BIEN ENTENDIDA</span><h2>${esc(l.title)}</h2><p class="wConcept">${esc(l.concept)}</p>${l.theory?l.theory.map(([h,t])=>`<h3>${esc(h)}</h3><p>${esc(t)}</p>`).join(''):''}${l.steps?`<ol class="wInstrumentSteps">${l.steps.map(([h,t])=>`<li><b>${esc(h)}</b><p>${esc(t)}</p></li>`).join('')}</ol>`:''}<div class="wCallout"><span>↳</span><div><b>Quédate con esto</b><p>${esc(l.example||l.task)}</p></div></div>`,
`<span class="wEyebrow">OBSERVAR / RELACIONAR SÍMBOLO Y FUNCIÓN</span><h2>Mira cómo encaja.</h2>${l.video?`<video controls playsinline preload="metadata" poster="videos/${esc(l.video)}.jpg"><source src="videos/${esc(l.video)}.mp4" type="video/mp4"><track kind="subtitles" srclang="es" label="Castellano" default src="videos/${esc(l.video)}.vtt"></video><p class="wMuted">Demostración conservada del curso · voz sintética integrada.</p>`:`<figure class="wLessonDiagram">${l.beginner?beginnerDiagram(l):c?circuitSvg(c.kind):art||''}</figure>`}<p>${esc(l.concept)}</p>`,
`<span class="wEyebrow">PREDECIR / COMPARAR DOS SITUACIONES</span><h2>¿Qué cambia y por qué?</h2><article class="wExample"><span>01 / OBSERVA</span><p>${esc(l.example||l.steps?.[0]?.[1]||l.concept)}</p></article><article class="wExample"><span>02 / CAMBIA UNA CONDICIÓN</span><p>${esc(l.contrast||l.transfer||l.steps?.[1]?.[1]||l.task)}</p></article>${l.trap?`<div class="wCaution"><b>Una confusión habitual</b><p>${esc(l.trap)}</p></div>`:''}`,
`<span class="wEyebrow">PRACTICAR / TU TURNO</span><h2>Piensa antes de medir.</h2><p class="wConcept">${esc(l.task||l.transfer)}</p><label class="wNoteLabel">Tu predicción y tu razonamiento<textarea id="wLessonNote" rows="6" placeholder="Espero encontrar… porque… Lo comprobaré entre…">${esc(notes[id]||st.note||'')}</textarea></label>${l.mission!==undefined?'<button id="wPractice3D" class="wPrimary">Abrir práctica en la placa 3D ↗</button>':''}${l.steps?'<button id="wPracticeSignals" class="wPrimary">Configurar los instrumentos ↗</button>':''}<p class="wMuted">El banco de apoyo calcula resistencias y filtros RC ideales. Las placas CAD se usan para explorar conectividad; no son una simulación eléctrica completa.</p>`,
`<span class="wEyebrow">COMPROBAR / CERRAR LA IDEA</span><h2>${esc(l.question||'Comprueba tu configuración')}</h2>${l.answers?`<div class="wAnswers">${l.answers.map((a,i)=>`<button data-answer="${i}"><span>${String.fromCharCode(65+i)}</span>${esc(a)}</button>`).join('')}</div>`:'<button id="wVerifyInstrument" class="wPrimary">Comprobar ajustes del instrumento</button>'}<p id="wQuizFeedback" role="status">${st.quiz?'✓ Comprensión comprobada.':'Comprueba tu respuesta para completar la lección.'}</p><p class="wMuted">${(notes[id]||st.note||'').trim()?'Razonamiento guardado.':'Escribe tu razonamiento en el paso Practicar.'}</p><button id="wFinish" class="wPrimary" ${!st.quiz||!(notes[id]||st.note||'').trim()?'disabled':''}>Completar y seguir →</button>`];
content.innerHTML=`<div class="wLessonHeader"><button id="wToRoute">← Mi ruta</button><span>BLOQUE ${b.index+1} / ${esc(b.title)}</span><span>${l.minutes||15} MIN</span></div><div class="wLessonTitle"><div><span class="wEyebrow">LECCIÓN ${route.indexOf(id)+1} / ${route.length}</span><h1>${esc(l.title)}</h1></div><span class="wLessonFraction">0${step+1}<em>/05</em></span></div><nav class="wStepTabs" aria-label="Pasos de la lección">${['Entender','Observar','Comparar','Practicar','Comprobar'].map((s,i)=>`<button data-step="${i}" aria-current="${i===step?'step':'false'}"><span>${i+1}</span>${s}</button>`).join('')}</nav><div class="wLessonLayout"><article class="wLessonText">${panels[step]}<div class="wLessonFoot"><button id="wPrevStep">${step?'← Anterior':'← Ruta'}</button><span>Paso ${step+1} de 5</span>${step<4?'<button id="wNextStep">Siguiente →</button>':''}</div></article><aside class="wLessonAside"><span class="wEyebrow">${b.index<6?'CONOCE LA PIEZA':'EL CIRCUITO DE REFERENCIA'}</span>${art||c&&`<figure>${circuitSvg(c.kind)}</figure>`||'<div class="wBlockGlyph">∿</div>'}<h3>${esc(b.title)}</h3><p>${esc(b.checkpoint)}</p><button id="wJumpBench">↓ Abrir banco de apoyo</button><div class="wLessonPosition"><b>Tu punto de partida</b><p>${esc(b.goal)}</p></div></aside></div><section id="wLessonBench" class="wLessonBench"></section>`;
$('wToRoute').onclick=()=>{phase=b.phase;navigate('course');};$('wPrevStep').onclick=()=>step?openLesson(id,step-1):$('wToRoute').click();$('wNextStep')?.addEventListener('click',()=>openLesson(id,step+1));content.querySelectorAll('[data-step]').forEach(btn=>btn.onclick=()=>openLesson(id,+btn.dataset.step));$('wLessonNote')?.addEventListener('input',e=>{notes[id]=e.target.value;progress[id]={...progress[id],note:e.target.value};save();});
api.bench.attach($('wLessonBench'),id);if($('benchBody')){$('benchBody').hidden=step!==3;$('benchFold').textContent=step===3?'Plegar instrumentos':'Mostrar instrumentos';$('benchFold').setAttribute('aria-expanded',String(step===3));}$('wJumpBench').onclick=()=>{$('benchBody').hidden=false;$('benchFold').textContent='Plegar instrumentos';$('benchFold').setAttribute('aria-expanded','true');$('wLessonBench').scrollIntoView({behavior:'smooth'});};
content.querySelectorAll('[data-answer]').forEach(btn=>btn.onclick=()=>{const ok=+btn.dataset.answer===l.correct;progress[id]={...progress[id],quiz:ok};save();content.querySelectorAll('[data-answer]').forEach(x=>{x.classList.remove('correct','incorrect');x.setAttribute('aria-pressed',String(x===btn));});btn.classList.add(ok?'correct':'incorrect');$('wQuizFeedback').textContent=ok?'✓ Correcto. '+(l.why||l.concept):'Revisa tu respuesta. '+(l.trap||l.concept);$('wFinish').disabled=!ok||!(notes[id]||st.note||'').trim();});
$('wVerifyInstrument')?.addEventListener('click',()=>{const ok=l.steps?.every(([, ,key,value])=>String($(key)?.value)===String(value));progress[id]={...progress[id],quiz:!!ok};save();$('wQuizFeedback').textContent=ok?'✓ Los ajustes coinciden con los pasos de esta práctica.':'Revisa los ajustes en Instrumentos: '+l.steps.map(x=>x[0]).join(', ');$('wFinish').disabled=!ok||!(notes[id]||st.note||'').trim();});
$('wFinish')?.addEventListener('click',()=>{if(!progress[id]?.quiz||!(notes[id]||st.note||'').trim())return;progress[id]={...progress[id],passed:true};save();openLesson(route[route.indexOf(id)+1]||route[0]);});$('wPractice3D')?.addEventListener('click',()=>openLab(null,l.mission));$('wPracticeSignals')?.addEventListener('click',()=>navigate('signals'));window.scrollTo?.({top:0,behavior:'instant'});}
function openLab(id,mission){park();screen='lab';updateNav();content.innerHTML='';lab.hidden=false;content.append(lab);if(mission!==undefined)api.launch(mission);else api.openBoard(id||'mosfet');lab.hidden=false;window.scrollTo?.({top:0,behavior:'instant'});window.dispatchEvent(new Event('resize'));}
function boardCatalog(){content.innerHTML=heading('EXPLORAR / DEL ESQUEMA A LA PLACA','Mira debajo<br><em>de cada conexión.</em>','Modelos girables, redes seleccionables y bloques funcionales. Elige una placa y trabaja sobre ella.')+`<div class="wCatalogFilters"><input id="wBoardSearch" type="search" placeholder="Buscar ordenador, audio, motor…" aria-label="Buscar placas"><select id="wBoardKind" aria-label="Tipo de placa"><option value="all">Todas las placas</option><option value="cad">CAD original</option><option value="didactic">Modelo didáctico</option></select><span id="wBoardCount"></span></div><div id="wBoards" class="wBoards"></div>`;
const render=()=>{const q=$('wBoardSearch').value.toLocaleLowerCase('es'),kind=$('wBoardKind').value;const list=api.boards.filter(b=>(kind==='all'||(kind==='cad')===(!b.educational&&!b.representative))&&`${b.title} ${b.domain||''}`.toLocaleLowerCase('es').includes(q));$('wBoardCount').textContent=list.length+' placas';$('wBoards').innerHTML=list.map((b,i)=>`<article class="wBoardCard"><div class="wBoardImage">${boardThumbnail(b)}<span>${b.educational||b.representative?'DIDÁCTICA':'CAD ORIGINAL'}</span></div><div class="wBoardBody"><small>${esc(b.domain||'Electrónica')}</small><h2>${esc(b.title)}</h2><div class="wBoardMetrics"><span>${b.elements.length} componentes</span><span>${b.nets.length} redes</span></div><button class="wPrimary" data-board="${b.id}">Abrir banco 3D <span>↗</span></button><details><summary>Origen y fidelidad</summary><p>${esc(b.fidelity||'Coordenadas y redes del CAD; cuerpos aproximados.')}</p></details></div></article>`).join('')||'<p>No hay resultados para estos filtros.</p>';$('wBoards').querySelectorAll('[data-board]').forEach(b=>b.onclick=()=>openLab(b.dataset.board));};$('wBoardSearch').oninput=render;$('wBoardKind').onchange=render;render();}
function experiment(){content.innerHTML=heading('EXPERIMENTAR / UNA SEÑAL, TRES INSTRUMENTOS','No adivines.<br><em>Haz la prueba.</em>','Cambia un valor, observa el efecto y explica la diferencia. Las medidas y las señales comparten el mismo modelo.')+`<div class="wExperimentIntro"><span>01 / CONFIGURA</span><span>02 / PREDICE</span><span>03 / MIDE</span><span>04 / EXPLICA</span></div><div id="wExperimentBench"></div><div class="wSectionHead"><h2>Biblioteca de circuitos</h2><input id="wCircuitSearch" placeholder="Buscar filtro, zener, transistor…" type="search" aria-label="Buscar circuitos"></div><div id="wCircuits" class="wCircuitGrid"></div>`;api.bench.attach($('wExperimentBench'),'libre');$('benchBody').hidden=false;$('benchFold').textContent='Plegar instrumentos';$('benchFold').setAttribute('aria-expanded','true');const render=()=>{const q=$('wCircuitSearch').value.toLocaleLowerCase('es');$('wCircuits').innerHTML=circuits.filter(c=>`${c.name} ${c.group}`.toLocaleLowerCase('es').includes(q)).map(c=>`<button class="wCircuitCard" data-circuit="${c.id}"><div>${circuitSvg(c.kind)}</div><small>${esc(c.group)}</small><h3>${esc(c.name)} ↗</h3><p>${esc(c.purpose)}</p></button>`).join('')||'<p>No hay circuitos que coincidan.</p>';$('wCircuits').querySelectorAll('[data-circuit]').forEach(b=>b.onclick=()=>circuitDetail(b.dataset.circuit));};$('wCircuitSearch').oninput=render;render();}
function circuitDetail(id){const c=circuits.find(x=>x.id===id);const d=document.createElement('dialog');d.className='wDialog';d.innerHTML=`<button class="wClose" aria-label="Cerrar">×</button><span class="wEyebrow">${esc(c.group)}</span><h2>${esc(c.name)}</h2><figure>${circuitSvg(c.kind)}</figure><p>${esc(c.recognize)}</p><div class="wFormula">${esc(c.formula||c.purpose)}</div><h3>Sigue el recorrido</h3><ol>${c.path.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><h3>Qué medir</h3><p>${esc(c.measure)}</p><p>${esc(c.expected)}</p><div class="wCaution"><b>Si algo falla</b><p>${esc(c.fault)}</p><p>${esc(c.trap)}</p></div>${c.board?'<button class="wPrimary" id="wCircuitBoard">Explorar en el banco ↗</button>':''}`;document.body.append(d);d.querySelector('.wClose').onclick=()=>d.close();d.addEventListener('close',()=>d.remove(),{once:true});d.querySelector('#wCircuitBoard')?.addEventListener('click',()=>{d.close();openLab(c.board,c.mission);});d.showModal();}
function diagnose(){content.innerHTML=heading('DIAGNOSTICAR / PIENSA COMO UN TÉCNICO','Una avería.<br><em>Una cadena de evidencias.</em>','Primero conoce el estado sano. Después formula una hipótesis, mide y comprueba si explica el síntoma.')+`<section class="wDiagnosticFeature"><div><span class="wEyebrow">CASO 01 / CONTROL DE UNA CARGA</span><h2>La salida no responde<br>al mando.</h2><p>El MOSFET parece seguir conduciendo. ¿Es el control, el transistor o el camino de la carga?</p><button id="wFaultCase" class="wPrimary">Investigar la avería ↗</button><small>Modelo DC didáctico · solo baja tensión virtual</small></div><div>${componentArt(4)}</div></section><div class="wPhaseGrid">${['Describe el síntoma','Plantea una hipótesis','Busca una medida','Comprueba el resultado'].map((t,i)=>`<article class="wPhaseCard"><span>0${i+1}</span><h3>${t}</h3><p>${['Qué funciona, qué falla y en qué condiciones.','Explica una causa que pueda contrastarse.','Elige puntos, referencia y valor esperado.','Descarta alternativas antes de concluir.'][i]}</p></article>`).join('')}</div><div class="wSectionHead"><h2>Entrena el razonamiento</h2></div><div class="wLessonList">${curriculum.filter(b=>b.phase===3).flatMap(b=>b.lessons).map(id=>`<button data-lesson="${id}"><span>↗</span><b>${esc(lessonFor(id).title)}</b><small>${passed(id)?'Completada':'Abrir lección'}</small></button>`).join('')}</div>`;$('wFaultCase').onclick=()=>openLab('mosfet',6);bindLessons();}
function notebook(){const written=Object.entries(notes).filter(([,v])=>v.trim());content.innerHTML=heading('MI CUADERNO / LO QUE HAS APRENDIDO','Tu razonamiento<br><em>también cuenta.</em>','Tus notas y el progreso se guardan en este navegador. Exporta una copia para conservarlos o trasladarlos a otro dispositivo.')+`<div class="wNotebookActions"><button id="wExportHere" class="wPrimary">Exportar copia ↓</button><label class="wImport">Importar copia<input id="wImport" type="file" accept="application/json,.json"></label><span id="wImportStatus" role="status"></span></div><div class="wNotes">${written.map(([id,n])=>`<article><span class="wEyebrow">${passed(id)?'✓ LECCIÓN COMPLETADA':'EN CURSO'}</span><h2>${esc(lessonFor(id)?.title||id)}</h2><p>${esc(n)}</p><button data-lesson="${esc(id)}">Volver a la lección ↗</button></article>`).join('')||'<div class="wEmpty"><span>▧</span><h2>Aquí empieza tu criterio.</h2><p>Escribe tu primera predicción en el paso Practicar de cualquier lección.</p><button class="wPrimary" data-go="course">Abrir el curso →</button></div>'}</div>`;bindLessons();$('wExportHere').onclick=exportProgress;$('wImport').onchange=async e=>{try{const f=e.target.files?.[0];if(!f)return;if(f.size>2000000)throw Error('El archivo es demasiado grande.');const data=JSON.parse(await f.text());if(data.format!=='elektronika-workshop-2'||!data.notes||typeof data.notes!=='object'||!data.progress||typeof data.progress!=='object')throw Error('El archivo no es una copia de Elektronika Lab 02.');for(const [k,v]of Object.entries(data.notes))if(route.includes(k)&&typeof v==='string')notes[k]=v.slice(0,20000);for(const [k,v]of Object.entries(data.progress))if(route.includes(k)&&v&&typeof v==='object')progress[k]={quiz:v.quiz===true,passed:v.passed===true,note:typeof v.note==='string'?v.note.slice(0,20000):''};save();notebook();$('wImportStatus').textContent='Copia importada.';}catch(err){$('wImportStatus').textContent=err.message;}};}
function exportProgress(){const data={format:'elektronika-workshop-2',exported:new Date().toISOString(),progress,notes,current};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='elektronika-lab-progreso.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('wExport').onclick=exportProgress;$('wResume').onclick=()=>openLesson(current?.id||next(),current?.step||0);$('wTheme').onclick=()=>{const dark=document.documentElement.dataset.theme!=='light';document.documentElement.dataset.theme=dark?'light':'dark';try{api.storage.setItem('circuitlab-theme',dark?'light':'dark');}catch{}};$('wThemeTop').onclick=()=>$('wTheme').click();document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>navigate(b.dataset.route));document.querySelector('.wBrand').onclick=e=>{e.preventDefault();navigate('home');};
// Scope's original tutorial can open the board; keep the new shell in charge.
document.addEventListener('circuitlab:page',e=>{if(e.detail==='lab'&&screen!=='lab')openLab(api.board().id);});
for(const [id,v]of Object.entries(progress))if(v?.note&&!notes[id])notes[id]=v.note;
navigate('home');return {navigate,openLesson,openLab};
}
